// Execute the actual client against controlled responses; no browser/network or dependencies.
const {test}=require('node:test');const assert=require('node:assert/strict');const vm=require('node:vm');const fs=require('node:fs');
function ui(){const nodes=new Map();class Element{constructor(){this.value='';this.hidden=false;this.events={};this.children=[];this.checked=false;this.open=false;this.isConnected=true;this.textWrites=0;}set textContent(value){this._text=value;this.textWrites++;}get textContent(){return this._text;}getAttribute(k){return this[k]??null;}setAttribute(k,v){this[k]=v;}showModal(){this.open=true;}close(){this.open=false;}focus(){this.focused=true;document.activeElement=this;}select(){this.selected=true;}addEventListener(k,f){this.events[k]=f;}replaceChildren(){const disconnect=n=>{n.isConnected=false;for(const child of n.children)disconnect(child);};for(const child of this.children)disconnect(child);this.children=[];}append(x){this.children.push(x);}}
 const node=id=>{if(!nodes.has(id))nodes.set(id,new Element());return nodes.get(id);};const pending=[];const document={getElementById:node,createElement:()=>new Element(),activeElement:null};const context={document,fetch:(url,opts)=>new Promise(resolve=>pending.push({url,opts,resolve})),setInterval:()=>{},setTimeout,clearTimeout,AbortController,Date,Number};vm.createContext(context);vm.runInContext(fs.readFileSync('web/operations/app.js','utf8'),context);
 const login=()=>{node('token').value='synthetic-operator-token';node('connect').events.submit({preventDefault(){}});};const respond=async(s,status=200)=>{pending.shift().resolve({ok:status===200,status,json:async()=>s});await new Promise(setImmediate);};return{node,pending,login,respond};}
const snapshot=()=>({version:2,journal:{schema:2,pages_used:80,pages_limit:8192,free_pages:0,page_size:4096,attempts_used:1,attempts_limit:100000,sessions_used:1,sessions_limit:1024,reserve_bytes:262144,exhausted_observed:false,last_success_at:Date.now()/1000,scope:"selected journal only"},read_at:Date.now()/1000,worker:{sampled_at:Date.now()/1000,state:'idle',queue:{next:9,pending:2,pending_bytes:64,budget:128}},attempts:1,unconfirmed:1,telemetry_dropped:0,unclosed_sessions:0,reporters:[],recent:[{updated_at:1,capture:{attempt:'<img src=x onerror=alert(1)>',observer:'collector',observed:2,locally_queued:1,unconfirmed:1,recording_gap:true,outcome:'completed'}}]});
test('auth is header-only; gap filtering and untrusted values use text',async()=>{const u=ui();u.login();assert.equal(u.pending[0].url,'/api/status');assert.equal(u.pending[0].opts.headers.Authorization,'Bearer synthetic-operator-token');assert.equal(u.pending[0].opts.credentials,'omit');assert.equal(u.node('token').value,'');await u.respond(snapshot());assert.equal(u.node('gaps').textContent,'1');assert.equal(u.node('acked').textContent,'7');assert.equal(u.node('rows').children[0].children[0].title,'<img src=x onerror=alert(1)>');assert.match(u.node('coverage-history').textContent,/unconfirmed/);u.node('gaps-only').checked=true;u.node('gaps-only').events.change();assert.equal(u.node('rows').children.length,1);});
test('late authenticated response cannot unlock a locked view',async()=>{const u=ui();u.login();u.node('lock').events.click();await u.respond(snapshot());assert.equal(u.node('data').hidden,true);assert.equal(u.node('rows').children.length,0);assert.equal(u.node('updated').textContent,'Locked');});
test('missing/stale data and HTTP failure cannot look healthy',async()=>{const u=ui();u.login();const s=snapshot();s.worker.sampled_at=1;await u.respond(s);assert.match(u.node('notice').textContent,/missing or stale/);u.node('refresh').events.click();await u.respond({},503);assert.equal(u.node('notice').className,'notice error');assert.match(u.node('updated').textContent,/Disconnected/);assert.equal(u.node('pending').textContent,'2');});
test('absent and stale capture reporters remain explicitly unknown',async()=>{const u=ui();u.login();const s=snapshot();s.unconfirmed=0;s.recent=[];await u.respond(s);assert.match(u.node('notice').textContent,/No active capture reporter/);assert.equal(u.node('empty').hidden,false);u.node('refresh').events.click();s.reporters=[{clean:false,updated_at:1}];s.unclosed_sessions=1;await u.respond(s);assert.match(u.node('notice').textContent,/reporter is stale/);});

test('fresh active sessions are current while historical losses remain visible',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;s.telemetry_dropped=7;s.worker.telemetry_failures=3;await u.respond(s);assert.equal(u.node('notice').className,'notice ');assert.match(u.node('notice').textContent,/Status is current/);assert.match(u.node('coverage-history').textContent,/1 unconfirmed.*7 health telemetry loss observations.*3 worker reports failed/);assert.match(u.node('telemetry').textContent,/3 worker reports failed/);});
test('delivery retries, unsampled unclosed sessions and future clocks cannot look current',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;s.worker.state='retrying';await u.respond(s);assert.match(u.node('notice').textContent,/delivery is retrying/);s.worker.state='idle';s.unclosed_sessions=2;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/no recent sampled heartbeat/);s.unclosed_sessions=1;s.worker.sampled_at=Date.now()/1000+3600;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/missing or stale/);});

test('future clock samples produce consistent badges and retain uncertain reporter history',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000+3600}];s.unclosed_sessions=1;await u.respond(s);assert.match(u.node('notice').textContent,/reporter is stale/);assert.match(u.node('coverage-history').textContent,/1 sampled unclosed sessions without a current heartbeat/);s.reporters[0].updated_at=Date.now()/1000;for(const stamp of [Date.now()/1000+3600,NaN]){s.worker.sampled_at=stamp;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/missing or stale/);assert.equal(u.node('worker').textContent,'Stale · idle');}});

test('unsampled sessions and summary loss units are explicit',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:1}];s.unclosed_sessions=4;s.telemetry_dropped=8;await u.respond(s);assert.match(u.node('coverage-history').textContent,/1 sampled unclosed sessions without a current heartbeat/);assert.match(u.node('coverage-history').textContent,/3 unclosed sessions outside the recent sample/);assert.match(u.node('telemetry').textContent,/8 health telemetry loss observations \(at least\)/);assert.doesNotMatch(u.node('telemetry').textContent,/capture updates lost/);});

test('journal capacity is independent, sticky and never an exact coverage claim',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;s.journal.exhausted_observed=true;s.journal.exhaustion_reason='sqlite_full';s.journal.reserve_bytes=0;await u.respond(s);assert.match(u.node('notice').textContent,/exhaustion was recorded/);assert.equal(u.node('journal-state').textContent,'Exhaustion recorded');assert.match(u.node('journal-scope').textContent,/lower bounds/);assert.equal(u.node('pending').textContent,'2');s.journal.exhausted_observed=false;s.journal.pages_used=8000;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/near its capacity limit/);s.journal.schema=1;s.journal.last_success_at=null;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('journal-state').textContent,/Legacy.*unknown/);assert.match(u.node('notice').textContent,/no recent successful observation/);});
test('unsupported status version retains visibly disconnected values',async()=>{const u=ui();u.login();await u.respond({...snapshot(),version:1});assert.match(u.node('notice').textContent,/Unsupported status version/);assert.match(u.node('updated').textContent,/Disconnected/);});

test('search is sample-bounded and inspection preserves exact untrusted identifiers',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('search').value='collector';u.node('search').events.input();assert.equal(u.node('rows').children.length,1);assert.match(u.node('sample-count').textContent,/does not scan older history/);const button=u.node('rows').children[0].children[0].children[0];button.events.click();assert.equal(u.node('inspector').open,true);assert.equal(u.node('attempt-id').value,'<img src=x onerror=alert(1)>');assert.equal(u.node('inspect-close').focused,true);await u.node('copy-id').events.click();assert.equal(u.node('attempt-id').selected,true);u.node('inspector').events.cancel({preventDefault(){}});assert.equal(u.node('inspector').open,false);assert.equal(button.focused,true);u.node('search').value='absent';u.node('search').events.input();assert.equal(u.node('rows').children.length,0);assert.match(u.node('empty').textContent,/latest sample/);});
test('locking clears rendered private metadata and closes the inspector',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('rows').children[0].children[0].children[0].events.click();u.node('lock').events.click();assert.equal(u.node('inspector').open,false);assert.equal(u.node('inspect-fields').children.length,0);assert.equal(u.node('attempt-id').value,'');assert.equal(u.node('journal-scope').textContent,'');assert.equal(u.node('coverage-history').textContent,'');assert.equal(u.node('pending').textContent,'');assert.equal(u.node('token').focused,true);});

test('reporter and attempt limits warn before exhaustion and preserve partial recording semantics',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;s.journal.sessions_used=1000;await u.respond(s);assert.match(u.node('notice').textContent,/capacity limit \(reporter sessions\)/);s.journal.sessions_used=1;s.journal.attempts_used=99000;u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/capacity limit \(attempts\)/);s.journal.exhausted_observed=true;s.journal.exhaustion_reason='session_limit';u.node('refresh').events.click();await u.respond(s);assert.match(u.node('notice').textContent,/Attempt summaries may still persist/);assert.equal(u.node('journal-state').textContent,'Reporter capacity exhausted');});
test('future persistence timestamps stay unknown',async()=>{const u=ui();u.login();const s=snapshot();s.journal.last_success_at=Date.now()/1000+3600;s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;await u.respond(s);assert.equal(u.node('journal-state').textContent,'Persistence unknown');assert.match(u.node('notice').textContent,/no recent successful observation/);});

test('polling preserves the focused attempt and inspector close returns to the replacement row',async()=>{const u=ui();u.login();await u.respond(snapshot());const first=u.node('rows').children[0].children[0].children[0];first.focus();u.node('refresh').events.click();await u.respond(snapshot());const second=u.node('rows').children[0].children[0].children[0];assert.notEqual(first,second);assert.equal(first.isConnected,false);assert.equal(second.focused,true);second.events.click();u.node('refresh').events.click();await u.respond(snapshot());const third=u.node('rows').children[0].children[0].children[0];u.node('inspect-close').events.click();assert.equal(third.focused,true);});
test('unchanged notices are not announced again on every poll',async()=>{const u=ui();u.login();const s=snapshot();s.reporters=[{clean:false,updated_at:Date.now()/1000}];s.unclosed_sessions=1;await u.respond(s);const before=u.node('notice').textWrites;u.node('refresh').events.click();await u.respond(s);assert.equal(u.node('notice').textWrites,before);s.unclosed_sessions=2;u.node('refresh').events.click();await u.respond(s);assert.equal(u.node('notice').textWrites,before+1);});
const overview=()=>({version:1,state:'completed',job:1,reason:null,last_job:1,last:{version:1,coverage:'observations-only',capture_completeness:'unknown',built_at:100,active:'a'.repeat(32),manifest_sha256:'b'.repeat(64),sources:[{generation:'a'.repeat(32),sealed_sha256:null,snapshot:{digest:'c'.repeat(64)}}],totals:{attempts:'1',sessions:'1',observed:'18446744073709551614',locally_queued:'2',unconfirmed:'1',attempts_with_gaps:'1',telemetry_dropped_lower_bound:'8',unclosed_sessions:'0'}}});
test('overview refresh is explicit authenticated POST with exact large counters',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-build').events.click();assert.equal(u.pending[0].url,'/api/overview/refresh');assert.equal(u.pending[0].opts.method,'POST');assert.equal(u.pending[0].opts.headers.Authorization,'Bearer synthetic-operator-token');await u.respond(overview());assert.match(u.node('overview-summary').textContent,/18,446,744,073,709,551,614 observed/);assert.match(u.node('overview-coverage').textContent,/completeness remains unknown/);assert.equal(u.node('overview-sources').children.length,1);});
test('lock clears overview and prevents a late result from repainting',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-load').events.click();await u.respond(overview());u.node('overview-build').events.click();u.node('lock').events.click();assert.equal(u.node('overview-summary').textContent,'');assert.equal(u.node('overview-sources').children.length,0);await u.respond(overview());assert.equal(u.node('overview-summary').textContent,'');assert.equal(u.node('data').hidden,true);});
test('failed or limited refresh labels the prior sample explicitly',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-load').events.click();await u.respond(overview());u.node('overview-build').events.click();const s=overview();s.state='capacity-limited';s.job=2;s.reason='memory bound reached';await u.respond(s);assert.match(u.node('overview-state').textContent,/Prior sample retained/);assert.match(u.node('overview-summary').textContent,/1 distinct attempts/);});
test('overview rejects malformed source lists and unsafe numeric counters before rendering',async()=>{for(const change of [s=>s.last.sources.push({...s.last.sources[0]}),s=>s.last.totals.observed=9007199254740992,s=>s.last.sources[0].generation='<script>',s=>s.last.sources[0].sealed_sha256='d'.repeat(64)]){const u=ui();u.login();await u.respond(snapshot());u.node('overview-load').events.click();const s=overview();change(s);await u.respond(s);assert.equal(u.node('overview-sources').children.length,0);assert.match(u.node('overview-state').textContent,/Invalid/);}});

test('build preempts an in-flight overview poll and ignores its stale reply',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-load').events.click();u.node('overview-build').events.click();assert.ok(u.pending[1], 'build must dispatch while the overview poll is pending');assert.equal(u.pending[1].url,'/api/overview/refresh');await u.respond(overview());assert.equal(u.node('overview-summary').textContent||'','');const s=overview();s.state='building';s.job=2;await u.respond(s);assert.match(u.node('overview-state').textContent,/building/);});
test('cancel preempts a poll while preserving server action order',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-build').events.click();const s=overview();s.state='building';s.job=2;await u.respond(s);u.node('overview-load').events.click();u.node('overview-cancel').events.click();assert.equal(u.pending.at(-1).url,'/api/overview/cancel');await u.respond(overview());assert.match(u.node('overview-state').textContent,/building/);s.state='cancelling';await u.respond(s);assert.match(u.node('overview-state').textContent,/cancelling/);});
test('a second action is queued behind an unfinished action, then dispatched',async()=>{const u=ui();u.login();await u.respond(snapshot());u.node('overview-build').events.click();u.node('overview-cancel').events.click();assert.equal(u.pending.length,1);assert.match(u.node('overview-state').textContent,/queued/);const s=overview();s.state='building';await u.respond(s);assert.equal(u.pending[0].url,'/api/overview/cancel');s.state='cancelled';await u.respond(s);assert.match(u.node('overview-state').textContent,/cancelled/);});

